const updated = getAdapter('band').editStructure(document.spec, {
  type: 'bands.replace',
  bands: [{ title: 'Merged' }],
  assignments: { a: 0 },
  removeNodeIds: ['b'],
})
if (updated.ok) {
  store.dispatch({
    id: 'merge-bands', label: 'Merge bands',
    expectedRevision: document.revision,
    commands: [{ type: 'spec.replace', spec: updated.value, references: 'prune-references' }],
